for predfile in "${explist[@]}"; do
    if [[ "$predfile" == *"timit"* ]]; then
        dataset="timit"
    elif [[ "$predfile" == *"buckeye"* ]]; then
        dataset="buckeye"
    else
        echo "Unknown dataset in file: $predfile"
        continue
    fi
	filename=${dataset}_$(basename -- "$predfile")
    evalname="${filename%.*}"
    outputfile="/work/nvme/bbjs/sbharadwaj/powsm/PhoneBench/exp/rq1/${evalname}.csv"
    echo "Evaluating $predfile -> $outputfile with eval name $evalname"
	python -m src.metrics.phone_recognition \
        --noisy_pr --prediction_file $predfile \
        --output_file $outputfile --evaluation_name $evalname &
done

wait